import logging
import os
import requests

log = logging.getLogger(__name__)

BREVO_API_KEY    = os.environ.get("BREVO_KEY", "")
REMITENTE_EMAIL  = os.environ.get("REMITENTE_EMAIL", "tamara.prieto@ata.es")
REMITENTE_NOMBRE = os.environ.get("REMITENTE_NOMBRE", "Oficina Acelera Pyme – A Coruna")
BREVO_API_URL    = "https://api.brevo.com/v3/smtp/email"

EMAIL_TEMPLATE = '<html>\n<body style="margin:0;padding:0;background:#f5f4f0;font-family:Arial,sans-serif">\n<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f4f0;padding:20px 0">\n<tr><td align="center">\n<table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n  <tr><td style="padding:0">\n    <img src="data:image/png;base64," alt="Oficina Acelera Pyme ATA" style="width:100%;display:block">\n  </td></tr>\n  <tr><td style="padding:32px 40px;color:#333333;font-size:14px;line-height:1.7">\n    CUERPO_PLACEHOLDER\n    <br><br>\n    FIRMA_PLACEHOLDER\n  </td></tr>\n  <tr><td style="padding:0">\n    <img src="data:image/png;base64," alt="Fondos Europeos Red.es" style="width:100%;display:block">\n  </td></tr>\n  <tr><td style="padding:20px 40px;background:#f8f7f4;border-top:1px solid #e4e2d9">\n    <p style="font-size:10px;color:#888888;line-height:1.6;margin:0">\n      <strong>Aviso legal</strong><br>\n      Segun la normativa vigente en proteccion de datos le informamos que su direccion de correo electronico junto con la informacion que nos facilite y nos haya facilitado, son tratados por FEDERACION NACIONAL DE ASOCIACIONES DE TRABAJADORES AUTONOMOS ATA como responsable del tratamiento con la finalidad de gestionar y mantener los contactos y relaciones que se produzcan como consecuencia de la relacion que mantiene con nosotros. La base juridica que legitima este tratamiento sera su consentimiento, el interes legitimo o la necesidad para gestionar una relacion contractual o similar.<br><br>\n      El plazo de conservacion de sus datos vendra determinado por la relacion que mantiene con nosotros.<br><br>\n      Si no desea seguir recibiendo comunicaciones a traves de esta via o si desea ejercitar sus derechos de acceso, rectificacion, cancelacion/supresion, oposicion, limitacion o portabilidad puede hacerlo a traves de correo electronico a <a href="mailto:rgpd@ata.es" style="color:#1B3A6B">rgpd@ata.es</a> indicando en el asunto "Proteccion de Datos" o enviando una solicitud por escrito a: FEDERACION NACIONAL DE ASOCIACIONES DE TRABAJADORES AUTONOMOS ATA Poligono El Granadal. Avenida Azabache s/n, esq. C/. Agata. 14014 Cordoba junto con prueba valida en derecho. En caso de considerar vulnerado su derecho a la proteccion de datos personales, podra interponer una reclamacion ante la Agencia Espanola de Proteccion de Datos (<a href="https://www.agpd.es" style="color:#1B3A6B">www.agpd.es</a>).<br><br>\n      La informacion contenida en este email es privilegiada para uso exclusivo del destinatario. Si ha recibido este mensaje por error, informenos en el telefono: <strong>900 101 816</strong> o reenvie a <a href="mailto:ata@ata.es" style="color:#1B3A6B">ata@ata.es</a><br><br>\n      Si no desea recibir mas comunicaciones, envienos un correo a <a href="mailto:oapcoruna@ata.es" style="color:#1B3A6B">oapcoruna@ata.es</a>.\n    </p>\n  </td></tr>\n</table>\n</td></tr>\n</table>\n</body>\n</html>'

def construir_html(cuerpo_texto, firma_html=""):
    cuerpo_html = cuerpo_texto.replace("\n", "<br>")
    html = EMAIL_TEMPLATE.replace("CUERPO_PLACEHOLDER", cuerpo_html)
    html = html.replace("FIRMA_PLACEHOLDER", firma_html)
    return html

def enviar_correo(destinatario_email, destinatario_nombre, asunto, cuerpo, firma_html=""):
    if not BREVO_API_KEY:
        return False, "BREVO_KEY no configurada"
    cuerpo_html = construir_html(cuerpo, firma_html)
    payload = {
        "sender": {"name": REMITENTE_NOMBRE, "email": REMITENTE_EMAIL},
        "to": [{"email": destinatario_email, "name": destinatario_nombre or destinatario_email}],
        "subject": asunto,
        "htmlContent": cuerpo_html,
        "textContent": cuerpo,
        "replyTo": {"email": REMITENTE_EMAIL, "name": REMITENTE_NOMBRE}
    }
    try:
        r = requests.post(BREVO_API_URL, json=payload, headers={
            "accept": "application/json",
            "content-type": "application/json",
            "api-key": BREVO_API_KEY
        }, timeout=30)
        if r.status_code in (200, 201):
            log.info(f"Correo enviado a {destinatario_email}")
            return True, None
        else:
            error = r.json().get("message", r.text)
            log.error(f"Brevo error {r.status_code}: {error}")
            return False, error
    except Exception as e:
        log.error(f"Error: {e}")
        return False, str(e)
